inline const char* MobileGLOpcodeName(MobileGLOpcode opcode) {
    const auto value = static_cast<uint32_t>(opcode);
    if (value == 0 || value > kMobileGLOpcodeCount) return "?";
    return kMobileGLOpcodeNames[value - 1];
}

